style.css:
@-moz-document domain("docs.google.com") {
/* Darken the main background around the slides */
  .docs-slides-smart-editor-canvas-container, 
  .kix-appview-editor {
    background-color: #121212 !important;
  }
  
  /* Style the top toolbar */
  #docs-toolbar-wrapper {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
  }
  
  /* Modernize filmstrip slide thumbnails background */
  .filmstrip-thumbnail-container {
    background-color: #1a1a1a !important;
    border-radius: 6px !important;
  }
}
